def _unit_for(values):
    m = max((abs(float(v)) for v in values), default=0.0)
    if m >= 1e9:
        return 1e9, "B"
    if m >= 1e6:
        return 1e6, "M"
    if m >= 1e3:
        return 1e3, "K"
    return 1.0, ""


def _fmt_u(v, div, suf):
    s = f"RM {abs(v) / div:,.2f}" + (f" {suf}" if suf else "")
    return f"({s})" if v < 0 else s


def _unit_lbl(suf):
    return "RM" + (f" {suf}" if suf else "")


def _fmt_m(v, dp=1):
    m = v / 1e6
    return f"({abs(m):,.{dp}f})" if m < 0 else f"{m:,.{dp}f}"


def _fmt_pct(num, den):
    if den == 0 or pd.isna(den):
        return "n.m."
    p = num / den
    return f"({abs(p):.2%})" if p < 0 else f"{p:.2%}"


def _b64(arr):
    return base64.b64encode(np.ascontiguousarray(arr).tobytes()).decode("ascii")


def _codes(series, vocab):
    m = {v: i for i, v in enumerate(vocab)}
    return series.map(m).to_numpy(dtype=np.uint8)


