def _read_any(path):
    """Read one file — .parquet or .csv/.csv.gz, auto-detected by extension."""
    if str(path).lower().endswith(".parquet"):
        return pd.read_parquet(path)
    return pd.read_csv(path)


def _read_multi(spec):
    """Read one dataset from a path, a glob pattern, or a list of paths
    (multi-part files are concatenated in sorted order)."""
    if isinstance(spec, (list, tuple)):
        paths = list(spec)
    elif any(ch in str(spec) for ch in "*?"):
        paths = sorted(glob(str(spec)))
    else:
        paths = [spec]
    if not paths:
        raise FileNotFoundError(f"No files match dataset input: {spec!r}")
    return pd.concat([_read_any(p) for p in paths], ignore_index=True)


def _load(file_daily_deposit, file_daily_transaction, file_ts_forecast, file_growth_matrix):
    # Daily files are optional (monthly cadence passes None for them).
    ds1 = _read_multi(file_daily_deposit) if file_daily_deposit is not None else None
    ds2 = _read_multi(file_daily_transaction) if file_daily_transaction is not None else None
    ds3 = _read_multi(file_ts_forecast)
    ds4 = _read_multi(file_growth_matrix)
    ds3["as_of_dt"] = pd.to_datetime(ds3["as_of_dt"])
    ds4["group_id"] = ds4["group_id"].astype(str)            # csv infers int
    ds3["Growth Segment"] = ds3["Growth Segment"].fillna("")
    if ds1 is not None:
        ds1["obs_date"] = pd.to_datetime(ds1["obs_date"])
        for c in ("MTD Variance", "YTD Growth"):
            if c not in ds1.columns:
                print(f"WARNING: DS1 is missing column '{c}' — check extract.")
    if ds2 is not None:
        ds2["txn_date"] = pd.to_datetime(ds2["txn_date"])
        ds2["txn_category"] = ds2["txn_category"].fillna("")
        if "MTD Variance" not in ds2.columns:
            print("WARNING: DS2 is missing column 'MTD Variance' — check extract.")
    return ds1, ds2, ds3, ds4


def _vocab_union(ds1, ds2, ds3):
    """Union vocabularies for S2/S3 slicers; DS3-domain vocab for S4."""
    prod8 = ["SAVING", "CURRENT", "AWFAR", "I-GAIN", "TDT", "WAFIYAH", "GIA", "IHSAN"]
    _dfs = [d for d in (ds1, ds2, ds3) if d is not None]
    seg12 = sorted(set().union(*[set(d["Segment"]) for d in _dfs]))
    region10 = (sorted(set(ds1["Region"])) if ds1 is not None
                else sorted(x for x in set(ds3["Region"]) if x != "Unknown"))
    occ23 = sorted(set().union(*[set(d["Occupation"]) for d in _dfs]))
    age6 = ["Under 18", "18-25", "26-35", "36-55", "Above 55", "NON-Individual"]
    ct3 = ["Individual", "SME", "Non-SME"]
    cats = ([""] + sorted(c for c in set(ds2["txn_category"]) if c != "")) if ds2 is not None else [""]
    # S4 (DS3 domain)
    prod5 = ["SAVING", "CURRENT", "AWFAR", "I-GAIN", "Unknown"]
    region11 = sorted(set(ds3["Region"]))
    return dict(prod8=prod8, seg12=seg12, region10=region10, occ23=occ23,
                age6=age6, ct3=ct3, cats=cats, prod5=prod5, region11=region11,
                dep2=["CASATIA", "Non-CASATIA"], status2=["Active", "Inactive"],
                etb2=["ETB", "NTB"],
                vc4=VC_ORDER, gs5=["Growing", "Broadening", "Shrinking", "Losing", "Stagnant"])


def _vc_codes(series, vocab):
    """Variance codes: 0-3 for the four active categories, 255 for Stable."""
    m = {v: i for i, v in enumerate(vocab)}
    return series.map(m).fillna(255).to_numpy(dtype=np.uint8)


def _payload(ds1, ds2, ds3, ds4, V, BASE, LAST, last_actual_month, forecast_months, monthly=False):
    flow = s1 = txn = None
    if not monthly:
      # ---- flow records: ALL DS1 cells (Driver/Depleter/Stable scoping is client-side)
      dims10 = ["Product", "Customer Type", "Deposit Type", "Segment", "Region",
                "Occupation", "Age Group", "Status", "ETB_NTB", "MTD Variance"]
      pv = ds1.pivot_table(index=dims10, columns="obs_date", values="Balance",
                           aggfunc="sum").fillna(0.0)
      pv = pv[sorted(pv.columns)]
      fx = pv.reset_index()
      balm = pv.to_numpy(dtype=np.float64)
      dlt = np.round(balm - balm[:, [0]]).astype(np.int32)     # daily deltas vs baseline, RM
      g = balm[:, -1] - balm[:, 0]
      flow = dict(
          prod=_b64(_codes(fx["Product"], V["prod8"])),
          ct=_b64(_codes(fx["Customer Type"], V["ct3"])),
          dt=_b64(_codes(fx["Deposit Type"], V["dep2"])),
          seg=_b64(_codes(fx["Segment"], V["seg12"])),
          region=_b64(_codes(fx["Region"], V["region10"])),
          occ=_b64(_codes(fx["Occupation"], V["occ23"])),
          age=_b64(_codes(fx["Age Group"], V["age6"])),
          status=_b64(_codes(fx["Status"], V["status2"])),
          etb=_b64(_codes(fx["ETB_NTB"], V["etb2"])),
          vcM=_b64(_vc_codes(fx["MTD Variance"], V["vc4"])),
          g=_b64(g.astype(np.float32)),
          bal0=_b64(balm[:, 0].astype(np.float32)),
          dlt=_b64(dlt),
          n=len(fx),
      )

      # ---- s1 aggregates (no slicers → precomputed daily portfolio series) ------
      daily = ds1.groupby("obs_date").agg(tot=("Balance", "sum"),
                                          ytd=("YTD Growth", "sum")).sort_index()
      s1 = dict(
          tot=[float(v) for v in daily["tot"]],
          mtd=[float(v - daily["tot"].iloc[0]) for v in daily["tot"]],
          ytd=[float(v) for v in daily["ytd"]],
      )

      # ---- txn records: DS2 non-stable in either perspective --------------------
      t = ds2.copy()                                    # all rows — Stable is selectable
      t["day"] = (t["txn_date"] - t["txn_date"].min()).dt.days
      keys = ["day", "txn_category", "dr_cr", "Product", "Customer Type", "Segment",
              "Region", "Occupation", "Age Group", "ETB_NTB", "MTD Variance"]
      agg = t.groupby(keys, sort=False).agg(amt=("total_txn_amt", "sum"),
                                            cnt=("total_txn_count", "sum")).reset_index()
      txn = dict(
          day=_b64(agg["day"].to_numpy(dtype=np.uint8)),
          cat=_b64(_codes(agg["txn_category"], V["cats"])),
          dr=_b64((agg["dr_cr"] == "D").to_numpy(dtype=np.uint8)),
          prod=_b64(_codes(agg["Product"], V["prod8"])),
          ct=_b64(_codes(agg["Customer Type"], V["ct3"])),
          seg=_b64(_codes(agg["Segment"], V["seg12"])),
          region=_b64(_codes(agg["Region"], V["region10"])),
          occ=_b64(_codes(agg["Occupation"], V["occ23"])),
          age=_b64(_codes(agg["Age Group"], V["age6"])),
          etb=_b64(_codes(agg["ETB_NTB"], V["etb2"])),
          vcM=_b64(_vc_codes(agg["MTD Variance"], V["vc4"])),
          amt=_b64(np.round(agg["amt"].to_numpy()).astype(np.float32)),
          cnt=_b64(np.minimum(agg["cnt"].to_numpy(), 65535).astype(np.uint16)),
          n=len(agg),
      )

    # ---- ts: DS3 per-group monthly balance & noa (48 months, row-major) ------
    months = sorted(ds3["as_of_dt"].unique())
    m_index = {m: i for i, m in enumerate(months)}
    n_m = len(months)
    gdims = (ds3.drop_duplicates("group_id")
             .set_index("group_id")[["Product", "Customer Type", "Segment",
                                     "Region", "Occupation", "Age Group", "ETB_NTB"]])
    gids = gdims.index.to_numpy()
    g_index = {g: i for i, g in enumerate(gids)}
    n_g = len(gids)
    bal = np.zeros((n_g, n_m), dtype=np.float32)
    noa = np.zeros((n_g, n_m), dtype=np.float32)
    gi = ds3["group_id"].map(g_index).to_numpy()
    mi = ds3["as_of_dt"].map(m_index).to_numpy()
    bal[gi, mi] = ds3["total_balance"].to_numpy(dtype=np.float32)
    noa[gi, mi] = ds3["total_noa"].to_numpy(dtype=np.float32)

    # Aggregate rows = any non-numeric group_id (e.g. 'OVERALL', '99999' absent
    # from DS3). Excluded from the Growth Segment map and hence from the matrix.
    gid_num = pd.to_numeric(ds4["group_id"], errors="coerce")
    excl = ds4.loc[gid_num.isna(), "group_id"].tolist()
    if excl:
        print(f"NOTE: DS4 aggregate rows excluded from group-level visuals: {excl}")
    d4 = ds4[gid_num.notna()].copy()
    d4.index = gid_num.dropna().astype(np.int64)
    gs_map = d4["Growth Segment"]
    gs = pd.Series(gids).map(gs_map)
    n_unmapped = int(gs.isna().sum())
    if n_unmapped:
        print(f"NOTE: {n_unmapped:,} DS3 groups have no DS4 Growth Segment — "
              "excluded from the Growth Matrix (still included in other S4 charts).")
    gs = gs.fillna("__UNMAPPED__")

    ts = dict(
        prod=_b64(_codes(gdims["Product"], V["prod5"])),
        ct=_b64(_codes(gdims["Customer Type"], V["ct3"])),
        seg=_b64(_codes(gdims["Segment"], V["seg12"])),
        region=_b64(_codes(gdims["Region"], V["region11"])),
        occ=_b64(_codes(gdims["Occupation"], V["occ23"])),
        age=_b64(_codes(gdims["Age Group"], V["age6"])),
        etb=_b64(_codes(gdims["ETB_NTB"], V["etb2"])),
        gs=_b64(gs.map({v: i for i, v in enumerate(V["gs5"])})
                .fillna(255).to_numpy(dtype=np.uint8)),
        bal=_b64(bal), noa=_b64(noa),
        nGroups=n_g, nMonths=n_m,
    )

    last_idx = m_index[pd.Timestamp(last_actual_month)]
    fc_end_idx = m_index[pd.Timestamp(forecast_months[-1])]
    meta = dict(
        months=[pd.Timestamp(m).strftime("%Y-%m-%d") for m in months],
        lastActualIdx=int(last_idx), fcEndIdx=int(fc_end_idx),
        nFc=int(fc_end_idx - last_idx),
        widen=WIDEN,
        days=([(BASE + pd.Timedelta(days=i)).strftime("%d %b") for i in range(15)]
              if BASE is not None else []),
        jan26Idx=m_index[pd.Timestamp("2026-01-31")],
    )
    if monthly:
        return dict(meta=meta, vocab=V, ts=ts)
    return dict(meta=meta, vocab=V, flow=flow, txn=txn, ts=ts, s1=s1)


# ----------------------------------------------------------------------------
# Section 1 KPI values (charts are JS-rendered in v2)
# ----------------------------------------------------------------------------
def _s1_kpis(ds1, BASE, LAST, annual_growth_target):
    tot = ds1.groupby("obs_date")["Balance"].sum().sort_index()
    ytd = float(ds1.loc[ds1["obs_date"] == LAST, "YTD Growth"].sum())
    doy = LAST.dayofyear
    days_in_year = 366 if LAST.is_leap_year else 365
    prorated = annual_growth_target * doy / days_in_year
    return dict(latest=tot.loc[LAST], growth=tot.loc[LAST] - tot.loc[BASE],
                base=tot.loc[BASE], days=(LAST - BASE).days,
                ytd=ytd, prorated=prorated, target=annual_growth_target,
                ach=ytd / prorated if prorated else float("nan"))


def compute_metrics(file_daily_deposit="data/daily_deposit.parquet",
                    file_daily_transaction="data/daily_transaction.parquet",
                    file_ts_forecast="data/deposit_ts_forecast_part*.parquet",
                    file_growth_matrix="data/growth_matrix.parquet",
                    baseline_date="2026-07-31", latest_date="2026-08-14",
                    last_actual_month="2026-07-31",
                    forecast_months=("2026-08-31", "2026-09-30", "2026-10-31"),
                    annual_growth_target=6.0e9):
    """Return every Python-derivable headline figure for use in remark f-strings.

    Each metric appears twice: a raw number (e.g. ``ytd``) and a ready-formatted
    RM string (e.g. ``ytd_f`` -> 'RM 3.86 B'). Growth Matrix and forecast totals
    are computed here so they can be interpolated into any {token} text field.
    Example:  caption_s1 = f"Portfolio grew {M['mtd_growth_f']} MTD ({M['ach_pct']:.0f}% of target)."
    """
    ds1, ds2, ds3, ds4 = _load(file_daily_deposit, file_daily_transaction,
                               file_ts_forecast, file_growth_matrix)
    BASE, LAST = pd.Timestamp(baseline_date), pd.Timestamp(latest_date)
    forecast_months = [pd.Timestamp(m) for m in forecast_months]
    LAM = pd.Timestamp(last_actual_month)

    def f(v):
        return _fmt_u(v, *_unit_for([v]))

    M = {}
    # ---- Section 1 (whole portfolio; skipped when no daily deposit file) -----
    if ds1 is not None:
      k = _s1_kpis(ds1, BASE, LAST, annual_growth_target)
      M.update(
        book_total=float(k["latest"]), latest=float(k["latest"]),
        base=float(k["base"]), mtd_growth=float(k["growth"]),
        mtd_growth_pct=float(k["growth"] / k["base"] * 100) if k["base"] else float("nan"),
        run_rate=float(k["growth"] / k["days"]) if k["days"] else float("nan"),
        days=int(k["days"]), ytd=float(k["ytd"]), prorated=float(k["prorated"]),
        target=float(k["target"]), ach=float(k["ach"]), ach_pct=float(k["ach"] * 100),
    )
    # ---- Forecast (DS3, CASATIA) --------------------------------------------
    fc_by_month = ds3.groupby("as_of_dt")["total_balance"].sum()
    last_actual_bal = float(fc_by_month.get(LAM, float("nan")))
    M["last_actual_bal"] = last_actual_bal
    M["last_actual_month_label"] = LAM.strftime("%b %Y")
    for i, fm in enumerate(forecast_months, start=1):
        v = float(fc_by_month.get(fm, float("nan")))
        M[f"fc_m{i}"] = v
        M[f"fc_m{i}_growth"] = v - last_actual_bal
        M[f"fc_m{i}_label"] = fm.strftime("%b %Y")
    # ---- Growth Matrix (DS3 @ last-actual, grouped by DS4 growth segment) ----
    gid_num = pd.to_numeric(ds4["group_id"], errors="coerce")
    d4 = ds4[gid_num.notna()].copy()
    d4.index = gid_num.dropna().astype("int64")
    gs_map = d4["Growth Segment"]
    at_la = ds3[ds3["as_of_dt"] == LAM].copy()
    at_la["gs"] = pd.to_numeric(at_la["group_id"], errors="coerce").map(gs_map)
    grp = at_la.groupby("gs").agg(bal=("total_balance", "sum"),
                                  noa=("total_noa", "sum"))
    for seg in ["Growing", "Broadening", "Shrinking", "Losing", "Stagnant"]:
        b = float(grp["bal"].get(seg, 0.0))
        n = float(grp["noa"].get(seg, 0.0))
        key = seg.lower()
        M[f"gm_{key}_bal"] = b
        M[f"gm_{key}_noa"] = n
    M["gm_total_bal"] = float(grp["bal"].sum())
    M["gm_total_noa"] = float(grp["noa"].sum())

    # ---- pre-formatted RM strings (suffix _f) --------------------------------
    for key in [k for k in list(M) if (k.endswith(("bal", "growth", "total",
                "latest", "base", "run_rate", "ytd", "prorated", "target",
                "mtd_growth")) or (k.startswith("fc_m") and k[4:].isdigit()))
                and isinstance(M[k], float)]:
        M[key + "_f"] = f(M[key])
    for key in ["gm_total_noa", "gm_growing_noa", "gm_broadening_noa",
                "gm_shrinking_noa", "gm_losing_noa", "gm_stagnant_noa"]:
        v = M[key]
        M[key + "_f"] = _fmt_u(v, *_unit_for([v])).replace("RM ", "") + " NOA"
    return M


