GM_LABEL_POS = {"Shrinking": (22, 78), "Growing": (78, 78),
                "Losing": (22, 22), "Broadening": (78, 22), "Stagnant": (50, 50)}


def _fmt_full(v):
    """Full-precision RM for tables; negatives red in parentheses."""
    s = f"{abs(v):,.0f}"
    return f'<span class="tneg">({s})</span>' if v < 0 else s


def _s1_table(ds1, BASE, LAST, fc_pivot=None, fc_month_label=""):
    """Product × Customer Type table: Balance / MTD Growth / YTD Growth, plus an
    optional next-month-end forecast group (CASATIA-only, K/M/B max-based, 2dp)."""
    CTS = ["Individual", "SME", "Non-SME"]
    CASATIA = ["SAVING", "CURRENT", "AWFAR", "I-GAIN"]
    NONCASA = ["TDT", "WAFIYAH", "GIA", "IHSAN"]
    last = ds1[ds1["obs_date"] == LAST]
    first = ds1[ds1["obs_date"] == BASE]

    def piv(df, val):
        return df.pivot_table(index="Product", columns="Customer Type",
                              values=val, aggfunc="sum").reindex(
            CASATIA + NONCASA).reindex(columns=CTS).fillna(0.0)

    bal = piv(last, "Balance")
    mtd = bal - piv(first, "Balance")
    ytd = piv(last, "YTD Growth")

    has_fc = fc_pivot is not None
    fc = (fc_pivot.reindex(CASATIA).reindex(columns=CTS).fillna(0.0)
          if has_fc else None)

    # Standardised display: one K/M/B unit per column group (max-based), 2 dp;
    # negatives red in parentheses.
    def _grp_unit(df, rows=None):
        d = df if rows is None else df.loc[rows]
        vals = list(d.to_numpy().ravel()) + list(d.sum(axis=1)) + [float(d.to_numpy().sum())]
        return _unit_for(vals)

    bU = _grp_unit(bal)
    mU = _grp_unit(mtd)
    yU = _grp_unit(ytd)
    fU = _grp_unit(fc, CASATIA) if has_fc else (1.0, "")

    def _fmt_g(v, unit):
        div, suf = unit
        s = f"{abs(v) / div:,.2f}" + (f" {suf}" if suf else "")
        return f'<span class="tneg">({s})</span>' if v < 0 else s

    def cells(row, g, unit):
        return "".join(f'<td class="{g}">{_fmt_g(v, unit)}</td>'
                       for v in list(row) + [row.sum()])

    def fcells(row):
        return "".join(f'<td class="g4">{_fmt_g(v, fU)}</td>'
                       for v in list(row) + [row.sum()])

    def fdash():
        return '<td class="g4">—</td>' * 4

    def tr(name, cls=""):
        b, m, yy = bal.loc[name], mtd.loc[name], ytd.loc[name]
        row = (f'<tr class="{cls}"><td class="pname">{name}</td>'
               + cells(b, "g1", bU) + cells(m, "g2", mU) + cells(yy, "g3", yU))
        if has_fc:
            row += fcells(fc.loc[name]) if name in CASATIA else fdash()
        return row + "</tr>"

    def subtotal(label, prods, cls):
        b, m, yy = bal.loc[prods].sum(), mtd.loc[prods].sum(), ytd.loc[prods].sum()
        row = (f'<tr class="{cls}"><td class="pname">{label}</td>'
               + cells(b, "g1", bU) + cells(m, "g2", mU) + cells(yy, "g3", yU))
        if has_fc:
            row += (fcells(fc.loc[prods].sum())
                    if all(p in CASATIA for p in prods) else fdash())
        return row + "</tr>"

    def _u(unit):
        return f" · RM {unit[1]}" if unit[1] else " · RM"

    groups = ["g1", "g2", "g3"] + (["g4"] if has_fc else [])
    head = ('<tr><th class="pname" rowspan="2">Product</th>'
            '<th colspan="4" class="hg1">Balance ' + LAST.strftime("%d %b") + _u(bU) + '</th>'
            '<th colspan="4" class="hg2">MTD Growth' + _u(mU) + '</th>'
            '<th colspan="4" class="hg3">YTD Growth' + _u(yU) + '</th>'
            + ('<th colspan="4" class="hg4">Next Month Fcst ' + fc_month_label
               + ' · CASATIA' + _u(fU) + '</th>' if has_fc else '')
            + '</tr><tr>'
            + ''.join(f'<th class="h{g}">Ind</th><th class="h{g}">SME</th>'
                      f'<th class="h{g}">Non-SME</th><th class="h{g} tot">Total</th>'
                      for g in groups) + '</tr>')
    body = ("".join(tr(p) for p in CASATIA)
            + subtotal("CASATIA Total", CASATIA, "sub")
            + "".join(tr(p) for p in NONCASA)
            + subtotal("Non-CASATIA Total", NONCASA, "sub")
            + subtotal("Grand Total", CASATIA + NONCASA, "grand"))
    return f'<div class="tblwrap"><table class="s1tbl">{head}{body}</table></div>'


def _gm_fig():
    GRID_MAX, MARGIN, CENTER_GAP, BOX_SIZE = 100, 5, 15, 40

    def qpath(corner):
        if corner == "UL":
            x = [MARGIN, MARGIN + BOX_SIZE, MARGIN + BOX_SIZE,
                 MARGIN + (BOX_SIZE - CENTER_GAP), MARGIN + (BOX_SIZE - CENTER_GAP), MARGIN]
            y = [GRID_MAX - MARGIN, GRID_MAX - MARGIN,
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP)),
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP)),
                 GRID_MAX - (MARGIN + BOX_SIZE), GRID_MAX - (MARGIN + BOX_SIZE)]
        elif corner == "UR":
            x = [GRID_MAX - (MARGIN + BOX_SIZE), GRID_MAX - MARGIN, GRID_MAX - MARGIN,
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP)),
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP)),
                 GRID_MAX - (MARGIN + BOX_SIZE)]
            y = [GRID_MAX - MARGIN, GRID_MAX - MARGIN, GRID_MAX - (MARGIN + BOX_SIZE),
                 GRID_MAX - (MARGIN + BOX_SIZE),
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP)),
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP))]
        elif corner == "LL":
            x = [MARGIN, MARGIN + BOX_SIZE, MARGIN + BOX_SIZE,
                 MARGIN + (BOX_SIZE - CENTER_GAP), MARGIN + (BOX_SIZE - CENTER_GAP), MARGIN]
            y = [MARGIN, MARGIN, MARGIN + (BOX_SIZE - CENTER_GAP),
                 MARGIN + (BOX_SIZE - CENTER_GAP), MARGIN + BOX_SIZE, MARGIN + BOX_SIZE]
        else:
            x = [GRID_MAX - MARGIN, GRID_MAX - MARGIN,
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP)),
                 GRID_MAX - (MARGIN + (BOX_SIZE - CENTER_GAP)),
                 GRID_MAX - (MARGIN + BOX_SIZE), GRID_MAX - (MARGIN + BOX_SIZE)]
            y = [MARGIN, MARGIN + BOX_SIZE, MARGIN + BOX_SIZE,
                 MARGIN + (BOX_SIZE - CENTER_GAP), MARGIN + (BOX_SIZE - CENTER_GAP), MARGIN]
        return "M " + " L ".join(f"{a},{b}" for a, b in zip(x, y)) + " Z"

    fig = go.Figure()
    for corner, seg in (("UL", "Shrinking"), ("UR", "Growing"),
                        ("LL", "Losing"), ("LR", "Broadening")):
        fig.add_shape(type="path", path=qpath(corner), fillcolor=GM_COLORS[seg],
                      line_width=0, opacity=0.9)
    fig.add_shape(type="rect", x0=31.5, y0=32.5, x1=68.5, y1=67.5,
                  fillcolor=GM_COLORS["Stagnant"], line_width=1, line_color="#888888")
    for seg, pos in GM_LABEL_POS.items():
        fig.add_annotation(x=pos[0], y=pos[1], showarrow=False,
                           text=f"<b>{seg}</b><br>…", align="center",
                           font=dict(size=18, color="#333333"))
    fig.update_xaxes(range=[0, 100], showgrid=False, zeroline=False, visible=True,
                     showline=True, linecolor="black", linewidth=2,
                     title="total_noa 6 Months Growth", tickvals=[])
    fig.update_yaxes(range=[0, 100], showgrid=False, zeroline=False, visible=True,
                     showline=True, linecolor="black", linewidth=2,
                     title="ticket_size 6 Months Growth", tickvals=[])
    fig.update_layout(height=600, margin=dict(l=60, r=20, t=20, b=60),
                      paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)")
    return fig


def _frag(fig, div_id):
    return pio.to_html(fig, full_html=False, include_plotlyjs=False, div_id=div_id,
                       config={"responsive": True, "displayModeBar": False},
                       default_width="100%", default_height=fig.layout.height)


# Expand-chart glyph. Defined once and shared by the Python `chexp()` helper (build-time
# buttons) and the JS `expBtn()` helper (runtime buttons, e.g. inside the why panels),
# so the two paths cannot drift apart.
EXP_SVG = ('<svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" '
           'stroke-width="1.7" stroke-linecap="round"><path d="M9.5 2.5h4v4M6.5 13.5h-4v-4"/>'
           '<path d="M13.5 2.5l-5 5M2.5 13.5l5-5"/></svg>')


