def _hero_merge(user):
    """Deep-merge the user's ``hero`` dict over HERO_DEFAULTS (None values fall back)."""
    H = {k: v for k, v in HERO_DEFAULTS.items() if k != "cards"}
    H["cards"] = {k: dict(v) for k, v in HERO_DEFAULTS["cards"].items()}
    for k, v in (user or {}).items():
        if k == "cards":
            for ck, cv in (v or {}).items():
                H["cards"].setdefault(ck, {})
                for kk, vv in (cv or {}).items():
                    if vv is not None:
                        H["cards"][ck][kk] = vv
        elif v is not None:
            H[k] = v
    return H


def _hero_html(H, sec_titles, masthead_color, detail=None):
    """Render the hero. ``{secN}`` / ``{secN:label}`` tokens in 'look' become
    in-dashboard links (page switch + scroll handled in JS).

    ``detail`` is the {card_key: {question, product, analytics, sales}} map from
    ``_load_framework_detail``; cards present in it get a 'Full detail' link that
    opens the shared panel below the rose. Cards absent from it render exactly as
    before."""
    def links(text):
        def rep(m):
            sec, lbl = m.group(1), m.group(2)
            lbl = lbl if lbl is not None else sec_titles.get(sec, sec)
            return f'<a data-sec="{sec}" href="#{sec}">{lbl}</a>'
        return re.sub(r"\{(sec\d)(?::([^}]*))?\}", rep, text)

    chev = ('<svg class="hx-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            'stroke-width="2"><path d="M6 9l6 6 6-6"/></svg>')
    detail = detail or {}
    det_label = H.get("detail_label") or "Full detail"
    det_close = H.get("detail_close_label") or "Close"
    det_q_label = H.get("detail_question_label") or "Question it answers"
    det_src = H.get("detail_source") or (
        "Source: Deposit Growth Navigation — Operating Framework (framework.xlsx · "
        "Framework sheet)")
    cards = []
    for key in ["sails", "radar", "compass", "catch", "rescue"]:
        c = H["cards"].get(key, {})
        if not c:
            continue
        status = (f'<div class="hx-stat"><i></i>{c["status"]}</div>' if c.get("status") else "")
        cards.append(
            f'<div class="hx-card {HERO_POS[key]}{" open" if c.get("open") else ""}" data-k="{key}">'
            f'<div class="hd"><div class="hx-ico">{HERO_ICONS[key]}</div>'
            f'<div class="hx-ttl"><div class="k">{c.get("kicker","")}</div><div class="n">{c.get("name","")}</div></div>{chev}</div>'
            f'<div class="hx-bd"><p>{c.get("desc","")}</p>'
            + (f'<div class="hx-look">{links(c["look"])}</div>' if c.get("look") else "")
            + status
            + (f'<div class="hx-more"><a class="hx-detbtn" data-det="{key}">{det_label} ▸</a></div>'
               if detail.get(key) else "")
            + '</div></div>')
    # ---- 'Full detail' panel (one shared panel below the rose) --------------
    det_panel = ""
    if detail:
        def esc_attr(t):
            return (str(t).replace("&", "&amp;").replace("<", "&lt;")
                    .replace(">", "&gt;").replace('"', "&quot;"))

        def role_html(t):
            """Keep the workbook's line breaks and their ORDER; each run of
            consecutive '1.'/'2.' lines becomes an <ol> in place, so prose that
            follows a numbered list stays after it."""
            lines = [l.strip() for l in str(t).splitlines() if l.strip()]
            if not lines:
                return ""
            out, run, prose = [], [], []

            def flush_prose():
                if prose:
                    out.append("<br>".join(esc_attr(l) for l in prose))
                    prose.clear()

            def flush_run():
                if run:
                    out.append("<ol>" + "".join(f"<li>{esc_attr(l)}</li>" for l in run) + "</ol>")
                    run.clear()

            for l in lines:
                m = re.match(r"^\d+[.)]\s*(.*)$", l)
                if m:
                    flush_prose()
                    run.append(m.group(1))
                else:
                    flush_run()
                    prose.append(l)
            flush_run()
            flush_prose()
            return "".join(out)

        blocks = []
        for key in ["compass", "sails", "catch", "radar", "rescue"]:
            d = detail.get(key)
            if not d:
                continue
            c = H["cards"].get(key, {})
            rows = "".join(
                f'<div class="hx-role"><div class="hx-rl">{lbl}</div>'
                f'<div class="hx-rv">{role_html(d.get(k, ""))}</div></div>'
                for lbl, k in [("Product", "product"), ("Analytics", "analytics"),
                               ("Sales", "sales")] if d.get(k))
            q = (f'<div class="hx-q"><span>{det_q_label}</span>{esc_attr(d["question"])}</div>'
                 if d.get("question") else "")
            blocks.append(
                f'<div class="hx-detblk" data-det="{key}">'
                f'<div class="hx-deth"><div class="hx-detico">{HERO_ICONS[key]}</div>'
                f'<div><div class="k">{c.get("kicker","")}</div>'
                f'<div class="n">{c.get("name","")}</div></div>'
                f'<button class="hx-detx" type="button">{det_close} ✕</button></div>'
                f'{q}<div class="hx-roles">{rows}</div>'
                f'<div class="hx-detsrc">{det_src}</div></div>')
        det_panel = f'<div class="hx-detwrap" id="hx-det">{"".join(blocks)}</div>'

    rose = HERO_ROSE_SVG.replace("__MASTHEAD__", masthead_color)
    lbls = json.dumps([H["expand_label"], H["collapse_label"]]).replace('"', "&quot;")
    return (f'<section class="hero" id="hero"><div class="hero-in">'
            f'<div class="hero-top"><div class="hx-compass">{rose}</div>'
            f'<div><h2>{H["headline"]}</h2><p class="hx-lead">{H["lead"]}</p>'
            f'<div class="hx-badges">'
            + (f'<span class="hx-badge">{H["badge_1"]}</span>' if H.get("badge_1") else "")
            + (f'<span class="hx-badge gold">{H["badge_2"]}</span>' if H.get("badge_2") else "")
            + '</div></div></div>'
            f'<div class="hx-fw" id="hx-fw">'
            f'<svg class="hx-rosebg" viewBox="0 0 200 200" aria-hidden="true"><use href="#hx-rose"/></svg>'
            f'<svg class="hx-needles" id="hx-needles" aria-hidden="true"></svg>'
            + "".join(cards) + '</div>'
            + det_panel
            + f'<div class="hx-foot"><div class="how">{H["how_to_read"]}</div>'
            f'<button id="hx-toggle" data-lbls="{lbls}">{H["expand_label"]}</button></div>'
            '</div></section>')


def _kpi(label, value, sub, cls="", vid="", sid=""):
    idv = f' id="{vid}"' if vid else ""
